={{ (() => {
  const submitted = $('Conversation State').item.json.crmPayload || {};
  const crm = $json || {};
  const saved = crm.lead || {};
  const detailUrl = crm.lead_detail_url || (($env.EIMATHS_CRM_BASE_URL || 'https://test-web.eimaths-th.com').replace(/\/$/, '') + '/admin/crm/leads/' + (crm.lead_id || crm.id || ''));
  const text = [
    'New lead from LINE OA',
    '',
    `Parent: ${saved.parent_name || submitted.parent_name || '-'}`,
    `Phone: ${saved.phone || submitted.phone || '-'}`,
    `LINE: ${submitted.line_display_name || '-'}`,
    `Student: ${saved.student_name || submitted.student_name || '-'}`,
    `Grade: ${saved.student_grade || submitted.student_grade || '-'}`,
    `Pain point: ${submitted.pain_point || '-'}`,
    `Interest: ${submitted.interest || '-'}`,
    `Contact time: ${submitted.preferred_contact_time || '-'}`,
    '',
    `Source: ${saved.utm_source || submitted.utm_source || submitted.line_source || 'line'}`,
    `Campaign: ${saved.utm_campaign || submitted.utm_campaign || 'unknown'}`,
    `Action: ${crm.action || 'created'}`,
    '',
    `Lead detail: ${detailUrl}`
  ].join('\n');

  return JSON.stringify({
    to: $env.LINE_MARKETING_GROUP_ID,
    messages: [{ type: 'text', text }]
  });
})() }}
